-- Drop the old projects table if it exists so we can recreate it with the correct schema
DROP TABLE IF EXISTS projects CASCADE;

CREATE TABLE projects (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    slug VARCHAR(255) UNIQUE NOT NULL,
    category VARCHAR(100) DEFAULT 'Residential',
    city VARCHAR(100) DEFAULT 'Mumbai',
    location VARCHAR(255) NOT NULL,
    cover_image TEXT NOT NULL,
    price_display VARCHAR(100) NOT NULL,
    price_numeric NUMERIC,
    status VARCHAR(50) NOT NULL,
    bhk_options VARCHAR(100),
    possession VARCHAR(100),
    rera_number VARCHAR(100),
    builder VARCHAR(255),
    min_bhk INT,
    max_bhk INT,
    description TEXT,
    tagline TEXT,
    gallery TEXT[], 
    amenities TEXT[], 
    highlights TEXT[],
    latitude DECIMAL,
    longitude DECIMAL,
    is_featured BOOLEAN DEFAULT FALSE,
    is_published BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

